import time
import urllib.error
import urllib.request


def open_url(url, attempts=4):
    for attempt in range(attempts):
        try:
            return urllib.request.urlopen(url, timeout=10)
        except urllib.error.HTTPError as err:
            if err.code != 429 or attempt == attempts - 1:
                raise
            time.sleep(int(err.headers.get("Retry-After", 2 ** attempt)))

import re

PATTERN = re.compile(r"^[\w.+-]+@[\w-]+(\.[\w-]+)+$")


def clean_email(value):
    if value is None:
        return None
    candidate = value.strip().lower()
    return candidate if PATTERN.match(candidate) else None


def clean_column(rows, key):
    for row in rows:
        row[key] = clean_email(row.get(key))
        yield row

