START = 0x7E


def checksum(data):
    return sum(data) & 0xFF


def frame(payload):
    body = bytes([len(payload)]) + payload
    return bytes([START]) + body + bytes([checksum(body)])


def test_frame_with_start_byte_in_payload():
    framed = frame(b"\x7e\x01")
    assert framed[0] == START
    assert framed[1] == 2
    assert framed[2:4] == b"\x7e\x01"
    assert framed[-1] == checksum(framed[1:-1])

class CueShifter:

    def __init__(self, offset_ms, floor_ms=0):
        self.offset_ms = offset_ms
        self.floor_ms = floor_ms

    def shift(self, start_ms, end_ms):
        start = max(start_ms + self.offset_ms, self.floor_ms)
        end = max(end_ms + self.offset_ms, start)
        return start, end
